/* HSK 4: one course, separate source data, practice and local progress. */
'use strict';
(() => {
const CONTENT_VERSION=new URL(document.currentScript?.src||location.href).searchParams.get('v')||'20261103-upper-10-lessons';
const KEY='hsk4-quest-v1';
const draftKey=(id=lesson.id)=>'hsk4-guided-v1-L'+String(id).padStart(2,'0');
const $=s=>document.querySelector(s), app=$('#app');
const E=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const defaults=()=>({version:1,known:{},wrong:{},history:[],visited:{},sections:{}});
let course,lessons=[],practices=[],lesson,practice,dictionary,overrides,upperDictionary,store=defaults(),session=null,flashIndex=0,flipped=false,flashFilter='all',flashOrder=[],search='',unknownOnly=false,hidePin=false,hideVi=false,recognition=null;
let dictionaryEntries=[],wordById=new Map(),baseDictionary=new Map(),noticeTimer;
const allWords=()=>lessons.flatMap(l=>l.words);
const lessonPath=(tab)=>`#lesson/${lesson.id}/${tab}`;
// Homepage cards and every study view share the same lesson palette.
const lessonThemes=[['#ba4d39','#fff1ed'],['#b66b20','#fff3e8'],['#9a7b16','#fff9e8'],['#728d22','#f4f8e5'],['#2d8b57','#e9f8ef'],['#248d82','#e7f7f4'],['#157e9e','#e8f6fa'],['#3773b8','#edf5ff'],['#5160be','#eef0ff'],['#7350b4','#f4efff']];
const lessonTheme=id=>lessonThemes[id-1]||lessonThemes[0];
function selectLesson(id){const next=lessons.find(l=>l.id===Number(id));if(!next)return false;if(lesson?.id!==next.id){search='';unknownOnly=false;flashOrder=[];flashFilter='all';flashIndex=0;flipped=false}lesson=next;practice=practices.find(p=>p.lesson===next.id);wordById=new Map(baseDictionary);for(const w of next.words)wordById.set(w.hanzi,w);dictionaryEntries=[...wordById.values()].sort((a,b)=>b.hanzi.length-a.hanzi.length);return true}
const modes=[
 ['hanzi','Hán tự → Nghĩa','🀄','Chọn nghĩa tiếng Việt của từ'],['meaning','Nghĩa → Hán tự','🧠','Nhận diện chữ Hán theo nghĩa'],['pinyin','Chọn pinyin','🔤','Nhận diện cách đọc của từ'],
 ['listen','Nghe chọn Hán tự','🎧','Nghe từ rồi chọn chữ Hán'],['listen-sentence','Nghe hiểu câu','🔊','Nghe câu rồi chọn câu tiếng Trung tương ứng'],['type','Gõ Hán tự','⌨️','Viết từ tương ứng với nghĩa'],['dictation','Nghe chép chính tả','✍️','Nghe và gõ lại từ'],
 ['cloze','Điền từ vào câu','🧩','Bốn lựa chọn theo ví dụ của bài'],['order','Sắp xếp từ thành câu','🔀','Khôi phục câu ví dụ trong tài liệu'],['translate','Dịch câu sang tiếng Trung','📝','Tự đối chiếu với câu mẫu'],
 ['reading','Đọc hiểu câu','📖','Đọc và đối chiếu bản dịch'],['speaking','Luyện nói','🎙️','Nghe, nói và tự đối chiếu'],['grammar','Trắc nghiệm ngữ pháp','📐','Luyện các cấu trúc của bài'],
 ['grammar-order','Sắp xếp câu ngữ pháp','📏','Luyện câu ví dụ ngữ pháp của bài'],['grammar-write','Viết câu ngữ pháp','✒️','Dịch câu và tự đối chiếu'],['passages','Đọc hiểu theo đoạn','📚','5 bài đọc độc lập · Mỗi bài 5 câu hỏi'],
 ['writing','Viết đoạn văn','📓','Viết theo chủ đề của bài học'],['mixed','Ôn tập tổng hợp','🏆','Kết hợp từ vựng và ngữ pháp']];
function notify(message){clearTimeout(noticeTimer);$('#notice').textContent=message;noticeTimer=setTimeout(()=>$('#notice').textContent='',5000)}
function readStored(){try{const x=JSON.parse(localStorage.getItem(KEY));if(x&&x.version===1){for(const k of ['known','wrong','visited','sections'])if(x[k]&&typeof x[k]==='object'&&!Array.isArray(x[k]))store[k]=x[k];if(Array.isArray(x.history))store.history=x.history.filter(validHistory)}}catch{notify('Không đọc được tiến độ đã lưu. Bạn vẫn có thể học; dữ liệu mới sẽ được lưu khi thiết bị cho phép.')}}
function validHistory(x){return x&&(x.lesson===undefined||x.lesson===null||Number.isInteger(x.lesson)&&x.lesson>=1&&x.lesson<=10)&&(x.lessonIds===undefined||Array.isArray(x.lessonIds)&&x.lessonIds.every(id=>Number.isInteger(id)&&id>=1&&id<=10))&&typeof x.mode==='string'&&Number.isInteger(x.total)&&x.total>0&&Number.isInteger(x.correct)&&x.correct>=0&&x.correct<=x.total&&Number.isInteger(x.autoCount)&&x.autoCount>=0&&x.correct<=x.autoCount&&Number.isInteger(x.selfCount)&&x.selfCount>=0&&x.autoCount+x.selfCount===x.total&&typeof x.date==='string'&&Number.isFinite(Date.parse(x.date))}
function save(){try{localStorage.setItem(KEY,JSON.stringify(store));return true}catch{notify('Chưa lưu được tiến độ. Hãy kiểm tra dung lượng hoặc chế độ riêng tư của trình duyệt.');return false}}
const known=(words=lesson.words)=>words.filter(w=>store.known[w.id]===true).length;
const bar=p=>`<div class="progress" role="progressbar" aria-label="Tỷ lệ từ đã thuộc" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${Math.round(p)}"><div style="width:${p}%"></div></div>`;
const action=(name,text,cls='',extra='')=>`<button type="button" class="${cls}" data-action="${name}" ${extra}>${text}</button>`;
const say=(text,label='🔊 Nghe')=>action('say',label,'',`data-text="${E(text)}"`);
function stop(){try{speechSynthesis.cancel()}catch{}try{recognition?.abort()}catch{}recognition=null;$('#gloss')?.remove()}
function shell(html){stop();const inLesson=location.hash.startsWith('#lesson/');if(inLesson)document.body.dataset.hskStudyView='lesson';else delete document.body.dataset.hskStudyView;const themeLesson=inLesson?lesson.id:location.hash==='#review/play'&&session?.lessonIds.length===1?session.lessonIds[0]:null;const [accent,tint]=themeLesson?lessonTheme(themeLesson):['#168b70','#eaf8f1'];if(themeLesson)document.body.dataset.hskThemeLesson=String(themeLesson);else delete document.body.dataset.hskThemeLesson;for(const [key,value] of Object.entries({'--accent':accent,'--soft':tint,'--accent-border':themeLesson?`color-mix(in srgb, ${accent} 34%, white)`:'#e4e8ee','--flash-bg':themeLesson?tint:'#ffffff'}))document.documentElement.style.setProperty(key,value);document.getElementById('hsk-site-header').style.setProperty('--hsk-nav-accent',themeLesson?accent:'#e54846');app.innerHTML=html;window.scrollTo(0,0)}
function enterView(hash){if(location.hash!==hash)history.pushState(null,'',hash)}
function activeHeader(){for(const a of document.querySelectorAll('.hsk-nav-actions a'))a.setAttribute('aria-current',a.hash===location.hash?'page':'false')}
function home(){const words=allWords(),n=known(words);shell(`<div class="qh-home"><section class="qh-top"><div class="qh-hero-copy"><span class="qh-overline">NEW HSK 4 · VERSION 3.0</span><h1>HSK 4 VERSION 3.0</h1><p>Thượng & Hạ · Từ vựng · Ngữ pháp · Trò chơi tương tác</p><span class="study-hero-label">Chọn một bài học bên dưới để bắt đầu <span aria-hidden="true">↓</span></span></div><div class="study-hero-art" aria-hidden="true"><img src="./assets/learning-book.svg" alt=""></div></section><section class="qh-main"><div class="qh-utility-row"><a class="qh-utility qh-utility-progress" href="#stats"><span class="qh-utility-icon">▥</span><span><strong>Tiến độ học</strong><small>Xem quá trình học của bạn</small></span><b>›</b></a><a class="qh-utility qh-utility-review" href="#review"><span class="qh-utility-icon" aria-hidden="true"><img src="./assets/review-book.svg" width="27" height="27" alt=""></span><span><strong>Ôn tập tổng hợp</strong><small>Luyện tập những nội dung đã học</small></span><b>›</b></a></div>
<div class="qh-list-header"><div><h2>HSK 4 Thượng — 上册</h2><p>Bài 1–10 · Đã mở ${lessons.length} bài · ${n}/${words.length} từ đã thuộc</p></div><label class="qh-search"><span aria-hidden="true">⌕</span><input id="lessonSearch" type="search" placeholder="Tìm bài học..." aria-label="Tìm bài học"></label></div>
<div class="qh-grid" id="qhGrid">${lessons.map((l,i)=>`<a class="qh-card lesson-card" href="#lesson/${l.id}/words" data-lesson-number="${l.id}" style="--lesson-accent:${lessonTheme(l.id)[0]};--lesson-tint:${lessonTheme(l.id)[1]}"><span class="study-art" aria-hidden="true"><span class="hsk3-lesson-emoji">${['🎓','🏠','📱','🤝','🍲','🏥','💼','🌳','💝','❄️'][i]}</span></span><div class="qh-info"><span class="qh-unit">Bài ${l.id}</span><div class="qh-title">${E(l.title)}</div><div class="qh-translation">${E(l.subtitle)}</div><div class="qh-facts"><span>📗 ${l.words.length} từ vựng</span><span>📘 ${l.grammar.length} ngữ pháp</span></div><div class="qh-progress" title="${Math.round(known(l.words)/l.words.length*100)}% từ đã thuộc"><span style="width:${known(l.words)/l.words.length*100}%"></span></div><span class="study-cta">Vào bài học <span aria-hidden="true">→</span></span></div></a>`).join('')}</div><p id="lessonEmpty" class="muted" hidden>Không tìm thấy bài học phù hợp.</p>
<section class="hsk4-lower dash-section"><div class="dash-section-title"><h2>HSK 4 Hạ — 下册</h2><span class="pill">Sắp ra mắt</span></div><p class="dash-hint">Bài 11–20 · Nội dung đang được chuẩn bị. Các bài chưa mở không tính vào tiến độ nội dung đã mở.</p><div class="hsk4-upcoming-lessons">${Array.from({length:10},(_,i)=>`<span class="pill">Bài ${i+11}</span>`).join('')}</div></section></section></div>`)}
function lessonHeader(tab){return `<button type="button" data-action="home">← Trang chủ</button><section class="unit-title-banner"><div class="unit-title-copy"><span class="unit-title-eyebrow">HSK 4 · THƯỢNG · BÀI ${String(lesson.id).padStart(2,'0')}</span><h2>Bài ${lesson.id}: <span class="hanzi">${clickable(lesson.title)}</span></h2><p class="muted">${E(lesson.subtitle)} · ${lesson.words.length} từ vựng</p></div></section><div class="tabs" role="navigation" aria-label="Nội dung bài học">${[['words','Từ vựng'],['grammar','Ngữ pháp'],['flash','Flashcard'],['games','Trò chơi']].map(([key,text])=>`<button type="button" class="${tab===key?'active':''}" data-action="tab" data-tab="${key}" ${tab===key?'aria-current="page"':''}>${text}</button>`).join('')}</div><section id="content"></section>`}
function openLesson(tab){store.visited[lesson.id]=true;store.sections[lesson.id+'/'+tab]=true;save();shell(lessonHeader(tab));if(tab==='grammar')renderGrammar();else if(tab==='flash'){flashIndex=0;flipped=false;renderFlash()}else if(tab==='games')renderGames();else renderWords()}
function example(w){return `<div class="example"><div class="hanzi">${E(w.example||w.hanzi)}</div><div class="pin">${E(w.examplePinyin||w.pinyin)}</div><p>${E(w.translation||'')}</p>${say(w.example||w.hanzi)}</div>`}
function renderWords(){const list=lesson.words.filter(w=>(!unknownOnly||!store.known[w.id])&&(!search||[w.hanzi,w.pinyin,w.meaning].some(x=>x.toLocaleLowerCase('vi').includes(search.toLocaleLowerCase('vi')))));
$('#content').innerHTML=`<div class="toolbar"><input id="wordSearch" type="search" placeholder="Tìm Hán tự, Pinyin, nghĩa..." aria-label="Tìm từ vựng" value="${E(search)}">${action('hide-pin',hidePin?'Hiện Pinyin':'Ẩn Pinyin','',`aria-pressed="${hidePin}"`)}${action('hide-vi',hideVi?'Hiện nghĩa':'Ẩn nghĩa','',`aria-pressed="${hideVi}"`)}${action('unknown-only','Chưa thuộc',unknownOnly?'active':'',`aria-pressed="${unknownOnly}"`)}</div><div class="tablewrap panel"><table class="hsk4-vocabulary"><thead><tr><th>STT</th><th>Hán tự</th><th>Pinyin</th><th>Nghĩa</th><th>Ví dụ và dịch</th><th>Học</th></tr></thead><tbody>${list.map(w=>`<tr class="word-card"><td>${Number(w.id.slice(-2))}</td><td><div class="hanzi">${clickable(w.hanzi)}</div>${say(w.hanzi,'🔊')}</td><td>${hidePin?'•••':`<span class="pin">${E(w.pinyin)}</span>`}</td><td>${hideVi?'•••':E(w.meaning)}<small class="hsk4-word-pos">${E(w.partOfSpeech)}</small></td><td><div class="hanzi" style="font-size:23px">${clickable(w.example)}</div>${hidePin?'':`<div class="muted pin">${E(w.examplePinyin)}</div>`}<div class="muted">${hideVi?'•••':E(w.translation)}</div>${say(w.example,'🔊 Nghe câu')}${w.sourceNote?`<small class="hsk4-source-note">Ví dụ/phiên âm đã được hiệu chỉnh để khớp nghĩa.</small>`:''}</td><td>${action('known',store.known[w.id]?'✓ Thuộc':'○ Chưa','',`data-id="${w.id}" aria-pressed="${!!store.known[w.id]}"`)}</td></tr>`).join('')}</tbody></table>${list.length?'':'<p class="muted">Không có từ phù hợp với bộ lọc.</p>'}</div>`}
function renderGrammar(){$('#content').innerHTML=`<div class="h2-section-intro"><div><span class="h2-eyebrow">NGỮ PHÁP · BÀI ${lesson.id}</span><h2>Ngữ pháp và mẫu câu</h2><p>${lesson.grammar.length} điểm ngữ pháp · Công thức · Ví dụ minh họa</p></div>${action('start','Luyện ngữ pháp →','primary','data-mode="grammar"')}</div>${lesson.grammar.map((g,i)=>`<article class="h2-ref-grammar grammar-card" id="h2-gram-${i}"><h3>${i+1}. ${E(g.name)}</h3><div class="h2-ref-formula"><b>✎ CÔNG THỨC</b><p>${E(g.formula)}</p></div><div class="h2-ref-theory"><p><b class="h2-ref-explain-label">📖 Giải thích:</b> ${E(g.explanation)}</p><p><b class="h2-ref-tip-label">💡 Cách dùng:</b> ${E(g.usage)}</p><p><b class="h2-ref-note-label">⚠ Lưu ý:</b> ${E(g.note)}</p></div><h4>Ví dụ minh họa</h4><div class="h2-ref-examples">${g.examples.map(e=>`<div class="h2-ref-example"><div class="h2-chinese">${clickable(e.hanzi)}</div><div class="h2-ref-pinyin">${E(e.pinyin)}${e.sourcePinyin?'<small class="hsk4-source-note">Đã hiệu chỉnh phiên âm trong tài liệu.</small>':''}</div><div class="h2-ref-translation">${E(e.translation)}</div>${action('say','🔊 Nghe câu','h2-audio',`data-text="${E(e.hanzi)}"`)}</div>`).join('')}</div>${g.phraseGroups?`<h4>Cụm từ thường gặp theo nhóm</h4>${g.phraseGroups.map(group=>`<h4>${E(group.label)}</h4><div class="h2-ref-examples">${group.items.map(e=>`<div class="h2-ref-example"><div class="h2-chinese">${clickable(e.hanzi)}</div><div class="h2-ref-pinyin">${E(e.pinyin)}</div><div class="h2-ref-translation">${E(e.translation)}</div>${say(e.hanzi)}</div>`).join('')}</div>`).join('')}`:''}${action('start','Luyện cấu trúc này →','',`data-mode="grammar" data-point="${g.id}"`)}</article>`).join('')}`}
const flashWords=()=>{const source=flashOrder.length?flashOrder.map(id=>lesson.words.find(w=>w.id===id)):lesson.words;return source.filter(w=>flashFilter==='all'||(flashFilter==='known'?store.known[w.id]:!store.known[w.id]))};
function renderFlash(){const list=flashWords();flashIndex=Math.max(0,Math.min(flashIndex,list.length-1));const w=list[flashIndex],n=known();$('#content').innerHTML=`<div class="panel hsk-unit-flash-panel"><div class="hsk-unit-flash-filters">${[['all',`Tất cả (${lesson.words.length})`],['known',`Đã thuộc (${n})`],['unknown',`Chưa thuộc (${lesson.words.length-n})`]].map(([filter,text])=>action('flash-filter',text,flashFilter===filter?'active':'',`data-filter="${filter}" aria-pressed="${flashFilter===filter}"`)).join('')}</div>${w?`<p class="muted hsk-unit-flash-status">Thẻ ${flashIndex+1}/${list.length} · ${store.known[w.id]?'Đã thuộc':'Chưa thuộc'}</p><div class="progress hsk-unit-flash-progress"><div style="width:${(flashIndex+1)/list.length*100}%"></div></div><div class="panel flash" id="hskUnitFlashCard" role="button" tabindex="0" aria-label="Lật thẻ ${E(w.hanzi)}" aria-pressed="${flipped}" data-action="flip"><div class="hanzi big">${E(w.hanzi)}</div>${flipped?`<h2>${E(w.pinyin)}</h2><h3 class="meaning">${E(w.meaning)}</h3><small class="hsk4-flash-pos">${E(w.partOfSpeech)}</small><div class="hsk-unit-flash-example">${E(w.example)}</div><p class="hsk3-example-pin">${E(w.examplePinyin)}</p><p class="hsk-unit-flash-translation">${E(w.translation)}</p>`:'<p class="muted">Chạm để xem nghĩa và ví dụ</p>'}</div><div class="toolbar" id="hskUnitFlashActions">${say(w.hanzi,'🔊 Nghe')}${action('flash-prev','← Trước','',flashIndex===0?'disabled':'')}${action('known',store.known[w.id]?'✓ Đã thuộc · Bỏ đánh dấu':'○ Đánh dấu đã thuộc','',`data-id="${w.id}" aria-pressed="${!!store.known[w.id]}"`)}${action('flash-shuffle','🔀 Trộn thẻ')}${action('flash-next','Tiếp →','primary')}</div>`:'<div class="panel">Không có từ nào trong nhóm này. Bạn có thể chọn nhóm khác ở phía trên.</div>'}</div>`}
function renderGames(){const groups=[['Từ vựng & ghi nhớ',['hanzi','meaning','pinyin']],['Nghe & viết',['listen','listen-sentence','type','dictation']],['Câu & ngữ pháp',['cloze','translate','order','reading','speaking','grammar']],['Đọc hiểu theo đoạn',['passages']],['Vận dụng ngữ pháp',['grammar-order','grammar-write']],['Viết đoạn văn & ôn tập',['writing','mixed']]];$('#content').innerHTML=`<div class="toolbar"><label>Số câu mỗi lượt: <select id="questionCount"><option>10</option><option selected>20</option><option>40</option></select></label></div><div class="game-groups">${groups.map(([title,ids])=>`<section><h3 class="game-group-title">${title}</h3><div class="grid">${ids.map(id=>{const [,name,icon,desc]=modes.find(m=>m[0]===id);return `<button type="button" class="game-card" data-action="start" data-mode="${id}"><span class="game-icon">${icon}</span><span><h3>${name}</h3><p>${desc}</p></span></button>`}).join('')}</div></section>`).join('')}</div>`}
function shuffle(a){const b=[...a];for(let i=b.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[b[i],b[j]]=[b[j],b[i]]}return b}
const normalize=s=>String(s).normalize('NFC').replace(/[\s。，！？、；：,.!?;:“”"‘’'（）()]/g,'');
const nameOf=id=>modes.find(m=>m[0]===id)?.[1]||id;
function vocabularyQuestion(w,mode){const owner=lessons.find(l=>l.words.some(x=>x.id===w.id)),v=practices.find(p=>p.lesson===owner.id).vocabulary.find(x=>x.wordId===w.id),q={mode,lessonId:owner.id,wordId:w.id,hanzi:w.hanzi,pinyin:w.pinyin,sentence:w.example,translation:w.translation,examplePinyin:w.examplePinyin,explanation:w.translation};
if(mode==='cloze')return {...q,prompt:v.cloze,answer:v.answer,options:shuffle(v.options),explanation:v.explanation};
if(mode==='order')return {...q,prompt:w.translation,answer:w.example,tokens:v.tokens};
if(['translate','reading','speaking'].includes(mode))return {...q,prompt:mode==='translate'?w.translation:w.example,answer:w.example,self:true};
const field=mode==='listen-sentence'?'example':mode==='hanzi'?'meaning':mode==='pinyin'?'pinyin':'hanzi';q.answer=w[field];q.prompt=mode==='hanzi'||mode==='pinyin'?w.hanzi:mode==='meaning'||mode==='type'?w.meaning:'Nghe và trả lời';
if(!['type','dictation'].includes(mode)){const others=[...new Set(owner.words.map(x=>x[field]).filter(x=>x!==q.answer))];q.options=shuffle([q.answer,...shuffle(others).slice(0,3)])}return q}
function grammarQuestions(mode,point,lessonIds=[lesson.id]){return practices.filter(p=>lessonIds.includes(p.lesson)).flatMap(p=>p.grammar.map(q=>({...q,lessonId:p.lesson}))).filter(q=>!point||q.pointId===point).map(q=>({...q,mode,prompt:mode==='grammar'?q.question:q.translation,answer:mode==='grammar'?q.answer:q.sentence,options:mode==='grammar'?shuffle(q.options):undefined,self:mode==='grammar-write',tokens:mode==='grammar-order'?tokenize(q.sentence).map(x=>x.text):undefined,examplePinyin:q.pinyin}))}
function start(mode,point){const count=Math.min(40,Math.max(1,Number($('#questionCount')?.value)||20));startWith(mode,count,point,lesson.words,lessonPath('games'))}
function startWith(mode,count,point,pool,back,readingId,lessonIds=[lesson.id]){if(mode==='passages'&&!readingId){renderReadingMenu();return}if(mode==='writing'){renderWriting();return}
let questions;if(mode==='passages'){const r=unitReadings().find(r=>r.id===readingId);if(!r){renderReadingMenu();notify('Bài đọc này chưa có nội dung.');return}questions=r.questions.map(q=>({...q,mode,prompt:q.question,options:shuffle(q.options),passage:r}));back=lessonPath('readings')}
else if(mode.startsWith('grammar'))questions=grammarQuestions(mode,point,lessonIds);
else if(mode==='mixed')questions=[...pool.flatMap(w=>['hanzi','meaning','cloze','listen'].map(m=>vocabularyQuestion(w,m))),...grammarQuestions('grammar',null,lessonIds)];
else questions=pool.map(w=>vocabularyQuestion(w,mode));
// Mixed rounds always include grammar while sampling vocabulary without replacement per submode.
if(mode==='mixed'){const gs=shuffle(questions.filter(q=>q.mode==='grammar')).slice(0,Math.min(4,Math.floor(count/3)));questions=shuffle([...shuffle(questions.filter(q=>q.mode!=='grammar')).slice(0,count-gs.length),...gs])}
else if(mode!=='passages')questions=shuffle(questions).slice(0,count);
if(!questions.length){notify('Không có câu hỏi phù hợp. Hãy chọn lại phạm vi ôn tập.');return}
enterView(readingId?lessonPath('readings/')+readingId:back==='#review'?'#review/play':lessonPath('play'));session={lessonIds,lessonId:back==='#review'?null:lesson.id,showPinyin:false,readingId,mode,questions,index:0,correct:0,autoCount:0,selfCount:0,answered:false,chosen:[],back,point,poolIds:pool.map(w=>w.id)};renderQuestion()}
function tokenize(text){let i=0,out=[];while(i<text.length){if(!/[\u3400-\u9fff]/.test(text[i])){out.push({text:text[i++]});continue}const w=dictionaryEntries.find(w=>text.startsWith(w.hanzi,i));if(w){out.push({text:w.hanzi,word:w});i+=w.hanzi.length}else{out.push({text:text[i++]})}}return out}
function clickable(text){return tokenize(text).map(x=>x.word?`<button type="button" class="h2-word lookup" data-action="lookup" data-word="${E(x.word.hanzi)}">${E(x.text)}</button>`:E(x.text)).join('')}
function renderChoices(q,reading=false){const chinese=q.mode==='listen-sentence'||!!q.passage;if(!chinese)return q.options.map((x,i)=>action('answer',E(x),reading?'h2-answer':'option',`data-index="${i}"`)).join('');return q.options.map((x,i)=>action('answer',`<span class="hanzi answer-text" lang="zh-CN">${E(x)}</span>`,`answer-choice ${reading?'h2-answer':'option'}`,`data-choice-index="${i}" data-index="${i}"`)).join('')}
function renderQuestion(){if(!session)return;if(session.index>=session.questions.length){finish();return}const s=session,q=s.questions[s.index];s.answered=false;s.chosen=[];s.tiles=q.tokens?shuffle(q.tokens.map((text,id)=>({text,id}))):[];if(q.passage){renderPassageQuestion(s,q);return}if(q.mode.startsWith('grammar')){renderGrammarQuestion(s,q);return}shell(`<div class="exercise-shell exercise"><a class="button back-inline" href="${s.back}">← ${s.back==='#review'?'Ôn tập tổng hợp':'Trở về Trò chơi'}</a><section class="panel exercise-panel" data-question-mode="${q.mode}"><div class="exercise-head"><span class="pill">${E(nameOf(q.mode))}</span><b>${s.index+1}/${s.questions.length}</b></div>${bar(s.index/s.questions.length*100)}${q.passage?`<span class="eyebrow">${E(q.passage.title)} · BÀI ĐỌC BỔ SUNG</span><p class="muted">Bấm vào từ tiếng Trung để xem pinyin và nghĩa ngay gần từ đó.</p><div class="h2-reading-text hanzi passage">${clickable(q.passage.text)}</div><div class="toolbar">${say(q.passage.text)}${action('toggle-detail','Hiện / ẩn pinyin','','data-target="passagePin"')}${action('toggle-detail','Hiện / ẩn bản dịch','','data-target="passageVi"')}</div><p id="passagePin" class="pin" hidden>${E(q.passage.pinyin)}</p><p id="passageVi" hidden>${E(q.passage.translation)}</p><span class="pill">${E(q.kind)}</span>`:''}
<h2 class="exercise-question ${['hanzi','pinyin','cloze','grammar','reading','speaking'].includes(q.mode)?'hanzi':''}">${['reading','speaking'].includes(q.mode)?clickable(q.prompt):E(q.prompt)}</h2>${q.mode==='hanzi'?`<p class="exercise-sub pin">${E(q.pinyin)}</p>`:''}
${['hanzi','pinyin','type','listen','dictation','listen-sentence'].includes(q.mode)?`<div class="exercise-actions">${say(q.mode==='listen-sentence'?q.sentence:q.hanzi,'🔊 Nghe phát âm')}${voicePicker()}</div>`:''}${q.mode==='speaking'?`<div class="row">${say(q.sentence)}${action('record','🎙️ Bắt đầu nhận diện')}</div><p class="muted">Trình duyệt có thể yêu cầu quyền micro. Kết quả nhận diện chỉ để tham khảo, không phải điểm phát âm.</p><p id="speechResult" role="status"></p>`:''}
<div id="answerArea">${q.options?`<div id="options" class="exercise-options options">${renderChoices(q)}</div>`:q.tokens?`<p class="muted">Bấm các từ theo thứ tự; bấm từ đã chọn để trả lại.</p><div id="chosenTiles" class="tiles" aria-label="Câu đã sắp xếp"></div><div id="availableTiles" class="tiles" aria-label="Các từ để chọn"></div>${action('submit-order','Kiểm tra câu','primary')}`:`<label for="typed">${q.mode==='reading'?'Viết cách hiểu của bạn bằng tiếng Việt':q.mode==='speaking'?'Câu trình duyệt nghe được — bạn có thể chỉnh sửa trước khi nộp':'Nhập câu trả lời bằng chữ Hán'}</label><textarea id="typed" lang="${q.mode==='reading'?'vi':'zh-CN'}" rows="3"></textarea>${action('submit-text',q.self?'Xem đáp án mẫu':'Kiểm tra','primary')}${q.self?'<p class="muted">Bài tự đối chiếu, không tính vào điểm đúng/sai.</p>':''}`}</div><div id="feedback" aria-live="polite"></div></section></div>`);if(q.tokens)renderTiles();}
function voicePicker(){const voices=(window.speechSynthesis?.getVoices()||[]).filter(v=>/^(zh|cmn)([-_]|$)/i.test(v.lang));let preferred='';try{preferred=localStorage.getItem('hsk4-voice')||''}catch{}return `<label class="voice-label">Giọng đọc <select id="voiceSelect"><option value="">Tự chọn giọng tiếng Trung tốt nhất</option>${voices.map(v=>`<option value="${E(v.voiceURI)}" ${v.voiceURI===preferred?'selected':''}>${E(v.name)} (${E(v.lang)})</option>`).join('')}</select></label>`}
const unitReadings=()=>practice.readings.filter(r=>(r.lesson??practice.lesson)===lesson.id);
function renderReadingMenu(){enterView(lessonPath('readings'));session=null;const readings=unitReadings();shell(lessonHeader('games'));$('#content').innerHTML=`<section class="reading-picker" style="--reading-accent:var(--accent)"><a class="button" href="${lessonPath('games')}">← Trò chơi</a><p class="reading-eyebrow">ĐỌC HIỂU MỞ RỘNG · UNIT ${lesson.id}</p><h2>Chọn bài đọc</h2><p>Chọn bất kỳ bài nào để bắt đầu. Không cần hoàn thành các bài trước.</p><div class="reading-picker-grid">${readings.map((r,i)=>{const result=store.history.find(h=>h.mode==='passages'&&h.readingId===r.id);return `<article class="reading-choice" data-reading-card="${r.id}"><span class="reading-eyebrow">BÀI ĐỌC ${i+1}</span><h3>${E(r.title)}</h3><p>${r.questions.length} câu hỏi</p><p class="reading-status ${result?'reading-completed':''}">${result?'Đã hoàn thành':'Chưa học'}</p><p class="reading-muted">${result?result.total:0}/${r.questions.length} câu đã trả lời · ${result?result.correct:0} đúng</p><a class="button reading-primary" href="${lessonPath('readings/')+r.id}" data-reading-id="${r.id}">${result?'Đọc và luyện lại':'Bắt đầu đọc'}</a></article>`}).join('')}</div></section>`}
function annotatedReading(text){return tokenize(text).map(t=>t.word?`<ruby>${E(t.text)}<rt>${E(t.word.pinyin)}</rt></ruby>`:E(t.text)).join('')}
function fitReadingAnswers(){
 const grid=document.querySelector('.reading-study .reading-options');if(!grid)return;
 const texts=[...grid.querySelectorAll('.answer-text')];if(!texts.length)return;
 const style=getComputedStyle(texts[0]),card=getComputedStyle(grid.querySelector('.answer-choice')),layout=getComputedStyle(grid);
 const context=document.createElement('canvas').getContext('2d');if(!context)return;
 context.font=`${style.fontStyle} ${style.fontWeight} ${style.fontSize} ${style.fontFamily}`;
 const spacing=parseFloat(style.letterSpacing)||0;
 const longest=Math.max(...texts.map(el=>context.measureText(el.textContent).width+Math.max(0,Array.from(el.textContent).length-1)*spacing));
 const fontSize=parseFloat(style.fontSize),width=grid.getBoundingClientRect().width,gap=parseFloat(layout.columnGap)||0;
 const inset=['paddingLeft','paddingRight','borderLeftWidth','borderRightWidth'].reduce((sum,key)=>sum+(parseFloat(card[key])||0),0);
 const required=Math.max(170,longest+inset+2);
 let columns=longest<=fontSize*8?4:longest<=fontSize*16?2:1;
 while(columns>1&&(width-gap*(columns-1))/columns<required)columns=columns===4?2:1;
 grid.style.setProperty('--reading-answer-columns',String(columns));grid.dataset.columns=String(columns);
}
function renderPassageQuestion(s,q){const r=q.passage;const pi=unitReadings().findIndex(x=>x.id===r.id);shell(`<div class="exercise hsk4-reading"><a class="button back-inline" href="${s.back}">← Danh sách bài đọc</a><section class="panel reading-study"><span class="pill">Bài đọc ${pi+1}/${unitReadings().length} · Câu ${s.index+1}/${s.questions.length}</span><h2>${E(r.title)}</h2><p class="hsk-reading-tip">👆 Bấm vào từ hoặc cụm từ để xem Pinyin và nghĩa tiếng Việt.</p><div class="hanzi h2-passage-text passage">${clickable(r.text)}</div><div class="toolbar reading-pinyin-control">${action('reading-pinyin',s.showPinyin?'🔤 Ẩn Pinyin':'🔤 Hiện Pinyin','',`id="readingPinyinToggle" aria-expanded="${!!s.showPinyin}" aria-controls="passagePin"`)}</div><div id="passagePin" class="reading-pinyin" ${s.showPinyin?'':'hidden'}>${annotatedReading(r.text)}</div><div class="toolbar">${say(r.text,'🔊 Nghe đoạn')}${action('toggle-detail','Hiện / ẩn bản dịch','','data-target="passageVi"')}</div><p id="passageVi" class="h2-reading-translation" hidden>${E(r.translation)}</p><p class="muted reading-source-note">Bài đọc bổ sung được biên soạn theo nội dung Unit ${lesson.id}.</p><hr><div class="h2-reading-question reading-question-area"><h3 lang="zh-CN">${clickable(q.prompt)}</h3><div id="answerArea"><div class="grid reading-options options">${renderChoices(q,true)}</div></div><div id="feedback" aria-live="polite"></div></div></section></div>`);fitReadingAnswers();document.fonts?.ready.then(fitReadingAnswers)}
function renderGrammarQuestion(s,q){const owner=lessons.find(l=>l.id===q.lessonId)||lesson,g=owner.grammar.find(g=>g.id===q.pointId);let controls;if(q.options)controls=`<h2 class="h2-chinese h2-question">${clickable(q.prompt)}</h2><div class="h2-options options">${q.options.map((x,i)=>action('answer',E(x),'h2-answer',`data-index="${i}"`)).join('')}</div>`;else if(q.tokens)controls=`<p class="game-prompt">${E(q.prompt)}</p><div id="chosenTiles" class="h2-tile-answer tiles" aria-label="Câu đã sắp xếp"></div><div id="availableTiles" class="h2-tiles tiles" aria-label="Các từ để chọn"></div>${action('submit-order','Kiểm tra','primary')}`;else controls=`<h2 class="game-prompt">${E(q.prompt)}</h2><label for="typed">Áp dụng: ${E(g?.name||'')}</label><textarea id="typed" class="h2-writing" rows="4" lang="zh-CN" placeholder="Viết câu bằng tiếng Trung…"></textarea>${action('submit-text','Đối chiếu câu mẫu','primary')}<p class="muted">Bài tự đối chiếu, không tính vào điểm đúng/sai.</p>`;shell(`<div class="exercise"><a class="button back-inline" href="${s.back}">← Trở về Trò chơi</a><section class="panel h2-exercise"><div class="row"><span class="pill">NGỮ PHÁP · BÀI ${owner.id}</span><span class="spacer"></span><b>${s.index+1}/${s.questions.length}</b></div>${bar(s.index/s.questions.length*100)}<p class="h2-exercise-label">${E(g?.name||'')}</p><div id="answerArea">${controls}</div><div id="feedback" aria-live="polite"></div></section></div>`);if(q.tokens)renderTiles()}
function renderTiles(){const s=session;$('#chosenTiles').innerHTML=s.chosen.map(id=>{const t=s.tiles.find(x=>x.id===id);return action('unpick',E(t.text),'',`data-index="${id}"`)}).join('');$('#availableTiles').innerHTML=s.tiles.filter(t=>!s.chosen.includes(t.id)).map(t=>action('pick',E(t.text),'',`data-index="${t.id}"`)).join('')}
function answer(value,index){const s=session;if(!s||s.answered)return;const q=s.questions[s.index];if(!String(value).trim()){notify('Hãy nhập câu trả lời trước khi đối chiếu.');return}const hadAnswerFocus=document.activeElement?.matches('[data-action="answer"]');s.answered=true;const correct=q.self?null:normalize(value)===normalize(q.answer);if(correct===null)s.selfCount++;else{s.autoCount++;if(correct)s.correct++;else if(q.wordId)store.wrong[q.wordId]=(store.wrong[q.wordId]||0)+1}save();
$('#answerArea').querySelectorAll('button:not([data-action="lookup"]),input,textarea').forEach(b=>b.disabled=true);
if(q.options)$('#answerArea').querySelectorAll('.option,.h2-answer').forEach((b,i)=>{if(q.options[i]===q.answer)b.classList.add('correct','is-correct');else if(i===index)b.classList.add('wrong','is-incorrect');if(b.matches('button.answer-choice')){const reviewed=document.createElement('div');reviewed.className=b.className;reviewed.dataset.choiceIndex=String(i);reviewed.dataset.graded='true';reviewed.innerHTML=`<div class="hanzi answer-text" lang="zh-CN">${clickable(q.options[i])}</div>`;b.replaceWith(reviewed)}});
$('#feedback').innerHTML=`<div class="result"><strong>${correct===null?'Tự đối chiếu với đáp án mẫu':correct?'✓ Chính xác':'Chưa đúng'}</strong><p class="${q.mode==='hanzi'||q.mode==='pinyin'||q.mode==='reading'?'':'hanzi'}">${q.mode==='listen-sentence'||q.passage?clickable(q.answer):E(q.mode==='reading'?q.translation:q.answer)}</p>${q.sentence?`<p class="hanzi">${E(q.sentence)}</p>`:''}${q.examplePinyin?`<p class="pin">${E(q.examplePinyin)}</p>`:''}<p>${E(q.explanation||q.translation)}</p>${q.self?'<p class="muted">Các cách diễn đạt khác có thể phù hợp. Bạn tự kiểm tra ý nghĩa, trật tự từ và ngữ pháp; lượt này không được chấm điểm tự động.</p>':''}${q.sentence?say(q.sentence):''}</div>${action('next',s.index+1===s.questions.length?'Xem kết quả':'Câu tiếp theo →','primary')}`;$('#feedback').scrollIntoView({block:'nearest'});if(hadAnswerFocus&&q.options)$('#feedback [data-action="next"]')?.focus({preventScroll:true})}
function finish(){const s=session;if(!s)return;const row={date:new Date().toISOString(),lesson:s.lessonId,lessonIds:s.lessonIds,readingId:s.readingId,mode:s.mode,correct:s.correct,total:s.questions.length,autoCount:s.autoCount,selfCount:s.selfCount};store.history.unshift(row);store.history=store.history.slice(0,500);save();session=null;shell(`<section class="exercise panel"><span class="eyebrow">HOÀN THÀNH LƯỢT LUYỆN TẬP</span><h1>${E(s.readingId?unitReadings().find(r=>r.id===s.readingId)?.title:nameOf(s.mode))}</h1>${s.autoCount?`<h2>${s.correct} / ${s.autoCount} câu đúng</h2>`:'<h2>Đã hoàn thành tự đối chiếu</h2>'}<p>${s.selfCount?s.selfCount+' câu tự đối chiếu, không tính điểm đúng/sai.':''}</p><div class="row">${action('retry','Luyện lại','primary',`data-mode="${s.mode}" data-reading="${E(s.readingId||'')}" data-point="${E(s.point||'')}" data-count="${s.questions.length}" data-pool="${E(s.poolIds.join(','))}" data-lessons="${s.lessonIds.join(',')}" data-back="${s.back}"`)}<a href="${s.back}" class="button">${s.readingId?'← Danh sách bài đọc':'← Quay lại'}</a><a href="#stats" class="button">Xem tiến độ</a></div></section>`)}
function renderWriting(){enterView(lessonPath('writing'));session=null;const w=practice.writing;let draft='';try{draft=localStorage.getItem(draftKey())||''}catch{}shell(`<a class="button back-inline" href="${lessonPath('games')}">← Quay lại trò chơi</a><section class="panel hsk4-writing"><span class="pill">Bài ${lesson.id} · Luyện viết có hướng dẫn</span><h2>✍️ Chủ đề: ${E(w.title||'Ngày đầu du học')}</h2><p class="game-prompt">${E(w.prompt)}</p><div class="answer-area"><h3>1. Từ vựng của bài này</h3><div class="guided-words">${w.suggestedWords.map(word=>`<span>${E(word)} · ${E(lesson.words.find(x=>x.hanzi===word)?.meaning||'')}</span>`).join('')}</div><h3>2. Cấu trúc gợi ý</h3><div class="guided-words">${w.suggestedGrammar.map(g=>`<span>${E(g)}</span>`).join('')}</div><h3>3. Gợi ý triển khai nội dung</h3><p>${(w.outline||['Giới thiệu việc chuẩn bị nhập học.','Kể về cách thích nghi với cuộc sống mới.','Nêu kế hoạch học tập và nghề nghiệp trong tương lai.','Kiểm tra trật tự từ và các cấu trúc ngữ pháp đã học.']).map(t=>'• '+E(t)).join('<br>')}</p><h3><label for="writingText">4. Viết đoạn văn của bạn</label></h3><textarea id="writingText" lang="zh-CN" rows="8" placeholder="Viết đoạn văn tiếng Trung tại đây…">${E(draft)}</textarea><div class="toolbar">${action('save-draft','💾 Lưu bài viết','primary')}${action('show-writing','💡 Xem đoạn mẫu')}${action('say-writing','🔊 Nghe bài viết')}</div><p id="draftStatus" class="draft-status" role="status"></p><p id="charCount" class="muted"></p><section id="writingSample" hidden><h3>Đoạn mẫu tham khảo</h3><div class="hanzi passage">${clickable(w.sample)}</div><p class="pin">${E(w.samplePinyin)}</p><p>${E(w.translation)}</p>${say(w.sample,'🔊 Nghe đoạn mẫu')}</section><p class="muted">Bài viết mở, không chấm ngữ nghĩa/phát âm tự động. Tự kiểm tra: đủ ý, dùng đúng cấu trúc, từ ngữ phù hợp và câu liên kết rõ ràng.</p></div></section>`);updateCharCount()}
function updateCharCount(){$('#charCount').textContent=($('#writingText').value.match(/[\u3400-\u9fff]/g)||[]).length+' chữ Hán'}
function saveDraft(){try{localStorage.setItem(draftKey(),$('#writingText').value);$('#draftStatus').textContent='Đã lưu bản nháp trên thiết bị này.'}catch{$('#draftStatus').textContent='Chưa lưu được bản nháp. Hãy sao chép bài viết trước khi rời trang.'}}
function dashboardBanner(title,label,description){return `<div class="dash-banner"><div><p class="dash-eyebrow">HSK 4 · VERSION 3.0 · ${label}</p><h1>${title}</h1><p>${description}</p></div><div class="dash-illustration" aria-hidden="true"><img src="./assets/progress-book.svg" alt=""></div></div>`}
function review(){const words=allWords(),n=known(words);shell(`<a href="#home" class="button back-inline">← Trang chủ HSK 4</a><div class="dash-shell">${dashboardBanner('Ôn tập tổng hợp','ÔN TẬP','Chọn nội dung đã học và luyện lại từ vựng bằng chế độ bạn yêu thích.')}<section class="dash-section"><div class="dash-section-title"><h2>Chọn bài học</h2><span class="dash-selection-count">${lessons.length}/${lessons.length} bài đã chọn</span></div><p class="dash-hint">Bài 1–10 đã mở. Quyển Hạ chưa tham gia ôn tập.</p><div class="dash-unit-grid">${lessons.map(l=>`<label class="dash-unit"><input type="checkbox" ${l.id===1?'id="reviewLesson"':''} data-review-lesson="${l.id}" checked><span><strong>Bài ${l.id}</strong> · ${E(l.title)}</span></label>`).join('')}</div></section><section class="dash-section"><div class="dash-section-title"><h2>Thiết lập lượt ôn tập</h2></div><p class="dash-hint">Chọn dạng câu hỏi rồi bắt đầu. Tiến độ sẽ tiếp tục được lưu trên thiết bị này.</p><div class="dash-form-row"><div><label class="dash-field-label" for="reviewScope">Nhóm từ</label><select class="dash-select" id="reviewScope"><option value="all">Toàn bộ từ</option><option value="unknown">Từ chưa thuộc (${words.length-n})</option><option value="wrong">Từ từng trả lời sai (${words.filter(w=>store.wrong[w.id]).length})</option></select></div><div><label class="dash-field-label" for="reviewMode">Chế độ luyện tập</label><select class="dash-select" id="reviewMode">${modes.filter(m=>['hanzi','meaning','listen','listen-sentence','type','cloze','mixed','grammar'].includes(m[0])).map(m=>`<option value="${m[0]}">${E(m[1])}</option>`).join('')}</select></div><div><label class="dash-field-label" for="reviewCount">Số câu</label><select class="dash-select" id="reviewCount"><option>10</option><option>20</option><option>40</option></select></div>${action('review-start','Bắt đầu ôn tập →','dash-action')}</div><p class="dash-hint">Ngữ pháp lấy từ các bài đã chọn; bộ lọc nhóm từ chỉ áp dụng cho câu hỏi từ vựng.</p></section></div>`)}
function updateReviewCounts(){const ids=[...document.querySelectorAll('[data-review-lesson]:checked')].map(b=>Number(b.dataset.reviewLesson)),words=lessons.filter(l=>ids.includes(l.id)).flatMap(l=>l.words);$('.dash-selection-count').textContent=ids.length+'/'+lessons.length+' bài đã chọn';$('#reviewScope option[value="unknown"]').textContent='Từ chưa thuộc ('+(words.length-known(words))+')';$('#reviewScope option[value="wrong"]').textContent='Từ từng trả lời sai ('+words.filter(w=>store.wrong[w.id]).length+')'}
function stats(){const words=allWords(),n=known(words),hist=store.history;const auto=hist.reduce((n,h)=>n+h.autoCount,0),correct=hist.reduce((n,h)=>n+h.correct,0);shell(`<a href="#home" class="button back-inline">← Trang chủ HSK 4</a><div class="dash-shell">${dashboardBanner('Tiến độ học tập','TIẾN ĐỘ','Theo dõi hành trình học, xem kết quả luyện tập và quản lý dữ liệu của bạn.')}<div class="dash-stats-grid"><div class="dash-stat"><span class="dash-stat-number">${n}</span><span class="dash-stat-label">Từ đã đánh dấu thuộc · ${words.length-n} từ chưa thuộc</span></div><div class="dash-stat"><span class="dash-stat-number">${hist.length}</span><span class="dash-stat-label">Lượt luyện tập đã lưu</span></div><div class="dash-stat"><span class="dash-stat-number">${auto?Math.round(correct/auto*100):0}%</span><span class="dash-stat-label">Tỉ lệ đúng · ${correct}/${auto} câu</span></div></div><section class="dash-section"><div class="dash-section-title"><h2>Tiến độ theo quyển</h2></div><p><b>Thượng:</b> ${n}/${words.length} từ trong nội dung đã mở · ${lessons.filter(l=>store.visited[l.id]).length} bài đã mở học / ${lessons.length} bài sẵn sàng.</p>${bar(n/words.length*100)}<p><b>Hạ:</b> Sắp ra mắt · chưa tính vào tiến độ.</p><p><b>Tổng nội dung HSK 4 đã mở:</b> ${Math.round(n/words.length*100)}% từ đã thuộc.</p><p class="dash-hint">Đây là tiến độ ghi nhớ tự đánh dấu của quyển Thượng, chưa phải tỷ lệ hoàn thành toàn bộ giáo trình 20 bài. Trạng thái “đã mở học” không đồng nghĩa đã nắm vững bài.</p></section><section class="dash-section"><div class="dash-section-title"><h2>Lịch sử luyện tập gần đây</h2><span>${Math.min(50,hist.length)} lượt gần nhất</span></div><div class="dash-history">${hist.length?`<div class="tablewrap"><table class="history"><thead><tr><th>Thời gian</th><th>Bài học</th><th>Chế độ</th><th>Kết quả</th></tr></thead><tbody>${hist.slice(0,50).map(h=>`<tr><td>${E(new Date(h.date).toLocaleString('vi-VN',{timeZone:'Asia/Bangkok'}))}</td><td>${h.lesson?'Bài '+h.lesson:'Bài '+(h.lessonIds||[1]).join(', ')}</td><td>${E(nameOf(h.mode))}</td><td>${h.autoCount?h.correct+'/'+h.autoCount+' câu đúng':'Tự đối chiếu'}${h.selfCount?' · '+h.selfCount+' câu tự đối chiếu':''}</td></tr>`).join('')}</tbody></table></div>`:'<div class="dash-empty">Bạn chưa có lượt luyện tập nào. Hãy bắt đầu học để xem kết quả tại đây.</div>'}</div></section><section class="dash-section"><div class="dash-section-title"><h2>Quản lý tiến độ</h2></div><p class="dash-hint">Xuất bản sao lưu để lưu lại kết quả, hoặc nhập dữ liệu đã lưu trước đó. Bản sao lưu chỉ chứa dữ liệu HSK 4 và bản nháp viết.</p><div class="dash-tools">${action('export','Xuất tiến độ JSON','dash-action')}<label class="dash-quiet dash-import">Nhập tiến độ JSON<input id="importFile" type="file" accept=".json,application/json" aria-label="Nhập tiến độ JSON"></label>${action('reset','Đặt lại tiến độ HSK 4','dash-quiet dash-danger')}</div></section></div>`)}
function showGloss(hanzi,target){const w=wordById.get(hanzi);if(!w)return;$('#gloss')?.remove();const box=document.createElement('aside');box.id='gloss';box.className='gloss';box.setAttribute('role','dialog');box.setAttribute('aria-label','Tra từ '+hanzi);box.innerHTML=`<div class="row spread"><span class="hanzi">${E(w.hanzi)}</span>${action('close-gloss','✕','','aria-label="Đóng tra từ"')}</div><p class="pin">${E(w.pinyin)}</p><p>${E(w.meaning)}</p>${say(w.hanzi)}`;document.body.append(box);const r=target.getBoundingClientRect(),b=box.getBoundingClientRect();box.style.left=Math.max(12,Math.min(innerWidth-b.width-12,r.left))+'px';box.style.top=Math.max(12,Math.min(innerHeight-b.height-12,r.bottom+b.height+12<innerHeight?r.bottom+8:r.top-b.height-8))+'px'}
function recordSpeech(){
 const SR=window.SpeechRecognition||window.webkitSpeechRecognition;
 const input=$('#typed'),status=$('#speechResult'),activeSession=session,questionIndex=session?.index;
 if(!input||!status||!activeSession||activeSession.answered)return;
 if(!SR){status.textContent='Thiết bị chưa hỗ trợ nhận diện giọng nói. Bạn có thể nghe câu mẫu rồi tự luyện nói.';return}
 try{
  recognition?.abort();const rec=new SR();recognition=rec;rec.lang='zh-CN';rec.interimResults=false;
  const current=()=>recognition===rec&&session===activeSession&&session.index===questionIndex&&!session.answered&&$('#typed')===input;
  rec.onresult=e=>{if(!current())return;const transcript=Array.from(e.results||[]).filter(r=>r.isFinal!==false).map(r=>r[0]?.transcript||'').join('').trim();if(!transcript){status.textContent='Chưa nghe rõ câu nói. Hãy thử lại.';return}input.value=transcript;input.dispatchEvent(new Event('input',{bubbles:true}));status.textContent='Đã điền câu nghe được vào ô trả lời. Bạn có thể sửa lại rồi bấm nộp.';input.focus()};
  rec.onerror=()=>{if(current())status.textContent='Chưa nhận diện được. Hãy kiểm tra quyền micro và thử lại.'};
  status.textContent='Đang nghe…';rec.start();
 }catch{if($('#speechResult')===status)status.textContent='Chưa mở được micro. Bạn có thể tự luyện với câu mẫu.'}
}
function readDrafts(){const drafts={};for(const l of lessons)drafts[l.id]=localStorage.getItem(draftKey(l.id))||'';return drafts}
function exportProgress(){let drafts={};try{drafts=readDrafts()}catch{}const url=URL.createObjectURL(new Blob([JSON.stringify({course:'hsk4',version:1,progress:store,draft:drafts[1]||'',drafts},null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='hsk4-tien-do.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
async function importProgress(file){if(!file)return;try{if(file.size>2e6)throw Error();const data=JSON.parse(await file.text()),x=data.progress;if(data.course!=='hsk4'||data.version!==1||x?.version!==1||typeof data.draft!=='string'||data.draft.length>100000)throw Error();for(const k of ['known','wrong','visited','sections'])if(!x[k]||typeof x[k]!=='object'||Array.isArray(x[k]))throw Error();if(!Array.isArray(x.history)||!x.history.every(validHistory))throw Error();const ids=new Set(allWords().map(w=>w.id));for(const [k,v]of Object.entries(x.known))if(!ids.has(k)||typeof v!=='boolean')throw Error();for(const [k,v]of Object.entries(x.wrong))if(!ids.has(k)||!Number.isInteger(v)||v<0)throw Error();const drafts=data.drafts??{1:data.draft};if(!drafts||typeof drafts!=='object'||Array.isArray(drafts))throw Error();for(const [id,text]of Object.entries(drafts))if(!lessons.some(l=>String(l.id)===id)||typeof text!=='string'||text.length>100000)throw Error();if(!confirm('Thay thế tiến độ và bản nháp HSK 4 trên thiết bị bằng bản sao lưu này?'))return;store={...defaults(),known:x.known,wrong:x.wrong,history:x.history.slice(0,500),visited:x.visited,sections:x.sections};if(!save())return;for(const l of lessons)localStorage.setItem(draftKey(l.id),drafts[l.id]||'');stats();notify('Đã nhập tiến độ HSK 4.')}catch{notify('Không nhập được file. Hãy chọn bản sao lưu HSK 4 hợp lệ hoặc kiểm tra dung lượng lưu trữ.')}}
function route(){stop();session=null;activeHeader();const hash=location.hash||'#home';if(hash==='#home')home();else if(hash==='#review'||hash==='#review/play')review();else if(hash==='#stats')stats();else{const m=hash.match(/^#lesson\/(\d+)\/(words|grammar|flash|games|readings|play|writing)(?:\/([^/]+))?$/);if(!m||!selectLesson(Number(m[1]))||(m[3]&&m[2]!=='readings')){home();notify('Bài học này chưa mở. Bạn có thể học Bài 1–10 quyển Thượng.');return}store.visited[lesson.id]=true;save();if(m[2]==='readings'){if(m[3])startWith('passages',5,null,lesson.words,lessonPath('readings'),m[3]);else renderReadingMenu()}else if(m[2]==='writing')renderWriting();else openLesson(m[2]==='play'?'games':m[2])}}
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b||b.disabled)return;const a=b.dataset.action;switch(a){
case 'home':location.hash='#home';break;
case 'tab':location.hash=lessonPath(b.dataset.tab);break;
case 'hide-pin':hidePin=!hidePin;renderWords();break;
case 'hide-vi':hideVi=!hideVi;renderWords();break;
case 'unknown-only':unknownOnly=!unknownOnly;renderWords();break;
case 'flash-filter':flashFilter=b.dataset.filter;flashIndex=0;flipped=false;renderFlash();break;
case 'flash-shuffle':flashOrder=shuffle(lesson.words.map(w=>w.id));flashIndex=0;flipped=false;renderFlash();break;
case 'say':window.speak(b.dataset.text);break;
case 'known':store.known[b.dataset.id]=!store.known[b.dataset.id];save();if(location.hash.endsWith('/flash'))renderFlash();else renderWords();break;
case 'flip':flipped=!flipped;renderFlash();break;
case 'flash-prev':flashIndex--;flipped=false;renderFlash();break;
case 'flash-next':flashIndex=(flashIndex+1)%flashWords().length;flipped=false;renderFlash();break;
case 'start':start(b.dataset.mode,b.dataset.point);break;
case 'retry':startWith(b.dataset.mode,Number(b.dataset.count),b.dataset.point,allWords().filter(w=>b.dataset.pool.split(',').includes(w.id)),b.dataset.back,b.dataset.reading,b.dataset.lessons.split(',').map(Number));break;
case 'answer':{const q=session.questions[session.index];answer(q.options[Number(b.dataset.index)],Number(b.dataset.index));break}
case 'submit-text':answer($('#typed').value);break;
case 'submit-order':answer(session.chosen.map(id=>session.tiles.find(t=>t.id===id).text).join(''));break;
case 'pick':if(session&&!session.answered&&!session.chosen.includes(Number(b.dataset.index))){session.chosen.push(Number(b.dataset.index));renderTiles()}break;
case 'unpick':if(session&&!session.answered){session.chosen=session.chosen.filter(id=>id!==Number(b.dataset.index));renderTiles()}break;
case 'next':if(session?.answered){session.index++;renderQuestion()}break;
case 'reading-pinyin':{const panel=$('#passagePin');panel.hidden=!panel.hidden;if(session)session.showPinyin=!panel.hidden;b.textContent=panel.hidden?'🔤 Hiện Pinyin':'🔤 Ẩn Pinyin';b.setAttribute('aria-expanded',String(!panel.hidden));break}
case 'toggle-detail':{const el=document.getElementById(b.dataset.target);el.hidden=!el.hidden;break}
case 'lookup':showGloss(b.dataset.word,b);break;
case 'close-gloss':$('#gloss')?.remove();break;
case 'record':recordSpeech();break;
case 'say-writing':if($('#writingText').value.trim())window.speak($('#writingText').value);else notify('Hãy nhập bài viết trước khi nghe.');break;
case 'save-draft':saveDraft();break;
case 'show-writing':saveDraft();$('#writingSample').hidden=false;break;
case 'review-start':{const ids=[...document.querySelectorAll('[data-review-lesson]:checked')].map(b=>Number(b.dataset.reviewLesson));if(!ids.length){notify('Hãy chọn ít nhất một bài học để ôn tập.');break}const scope=$('#reviewScope').value,mode=$('#reviewMode').value;const pool=lessons.filter(l=>ids.includes(l.id)).flatMap(l=>l.words).filter(w=>scope==='all'||scope==='unknown'&&!store.known[w.id]||scope==='wrong'&&store.wrong[w.id]);if(!pool.length&&mode!=='grammar'){notify('Không có từ trong nhóm này. Hãy chọn nhóm khác.');break}startWith(mode,Number($('#reviewCount').value),null,pool,'#review',null,ids);break}
case 'export':exportProgress();break;
case 'reset':if(confirm('Xóa tiến độ và bản nháp HSK 4 trên thiết bị này?')){try{localStorage.removeItem(KEY);for(const l of lessons)localStorage.removeItem(draftKey(l.id));store=defaults();stats()}catch{notify('Chưa xóa được tiến độ trên thiết bị.')}}break;
}});
document.addEventListener('keydown',e=>{if(e.key==='Escape')$('#gloss')?.remove();if((e.key==='Enter'||e.key===' ')&&e.target.id==='hskUnitFlashCard'){e.preventDefault();flipped=!flipped;renderFlash()}});
document.addEventListener('input',e=>{if(e.target.id==='lessonSearch'){const q=e.target.value.toLocaleLowerCase('vi');let count=0;for(const c of document.querySelectorAll('.lesson-card')){const match=('Bài '+c.dataset.lessonNumber+' '+c.textContent).toLocaleLowerCase('vi').includes(q);c.hidden=!match;if(match)count++}$('#lessonEmpty').hidden=count>0;}if(e.target.id==='wordSearch'){const start=e.target.selectionStart;search=e.target.value;renderWords();$('#wordSearch').focus();$('#wordSearch').setSelectionRange(start,start)}if(e.target.id==='writingText'){updateCharCount();saveDraft()}});
document.addEventListener('change',e=>{const id=e.target.id;if(e.target.matches('[data-review-lesson]'))updateReviewCounts();if(id==='voiceSelect')window.hskChooseSpeechVoice(e.target.value);if(id==='unknownOnly'){unknownOnly=e.target.checked;renderWords()}if(id==='hidePin'){hidePin=e.target.checked;renderWords()}if(id==='hideVi'){hideVi=e.target.checked;renderWords()}if(id==='importFile')importProgress(e.target.files[0])});
window.addEventListener('resize',()=>{$('#gloss')?.remove();fitReadingAnswers()});
async function init(){try{const load=async name=>{const r=await fetch('./data/'+name+'?v='+encodeURIComponent(CONTENT_VERSION),{cache:'no-cache'});if(!r.ok)throw Error(name);return r.json()};
[course,dictionary,overrides,upperDictionary]=await Promise.all(['course.json','dictionary.json','dictionary-overrides.json','dictionary-upper.json'].map(load));
const bundles=await Promise.all(course.lessons.map(async entry=>{const [l,p]=await Promise.all([load(entry.content),load(entry.practice)]);if(l.id!==entry.id||p.lesson!==entry.id)throw Error('lesson');return [l,p]}));lessons=bundles.map(b=>b[0]);practices=bundles.map(b=>b[1]);
for(const w of dictionary)if(w.hanzi&&w.pinyin&&w.meaning)baseDictionary.set(w.hanzi,w);for(const w of upperDictionary)baseDictionary.set(w.hanzi,w);for(const w of allWords())baseDictionary.set(w.hanzi,w);for(const w of overrides)baseDictionary.set(w.hanzi,w);selectLesson(1);readStored();window.addEventListener('hashchange',route);route();
// Read-only diagnostics for source audit and browser checks.
window.HSK4={get lesson(){return lesson},get practice(){return practice},lessons,practices,storageKey:KEY,getSession:()=>session,tokenize};
}catch{app.innerHTML='<section class="panel"><h1>Chưa tải được bài học</h1><p>Hãy kiểm tra kết nối và tải lại trang. Nếu mở file trực tiếp, hãy dùng đường dẫn website HSK Learning.</p><a class="button" href="../index.html">← Trang chủ HSK Learning</a></section>'}}
init();
})();
